  let sprite: any =gSprites[gBattlerSpriteIds[B_POSITION_OPPONENT_RIGHT]];

      sprite.x2 = 0;
      sprite.y2 = 0;
      sprite.x = GetBattlerSpriteCoord(B_POSITION_OPPONENT_RIGHT, BATTLER_COORD_X);
